    "\n"
    "    <h3>Checkpoint tampering</h3>\n"
    "    <div style=\"display:flex; gap:8px; margin-bottom:6px; align-items:center\">\n"
    "      <select id=\"k-svc\"></select>\n"
    "      <label class=\"cb\"><input type=\"checkbox\" id=\"k-restart\" checked> restart after</label>\n"
    "    </div>\n"
    "    <button class=\"btn small\" data-k=\"corrupt\">Corrupt newest</button><button class=\"btn small\" data-k=\"withhold\">Withhold</button><button class=\"btn small\" data-k=\"corrupt-both\">Corrupt both</button><button class=\"btn small\" data-k=\"restore\">Restore</button><button class=\"btn small\" data-k=\"clear\">Clear</button>\n"
    "\n"
    "    <h3>Supervisor &amp; watchdog</h3>\n"
    "    <button class=\"btn danger\" data-q=\"do=supkill\"><span class=\"n\">S</span><span>Kill the supervisor<span class=\"h\">watchdog takes over, services adopted</span></span></button>\n"
    "    <button class=\"btn danger\" data-q=\"do=suphang\"><span class=\"n\">S</span><span>Hang the supervisor<span class=\"h\">heartbeat loss detected by the watchdog</span></span></button>\n"
    "    <button class=\"btn danger\" data-q=\"do=wdkill\"><span class=\"n\">W</span><span>Kill the watchdog<span class=\"h\">supervisor restarts it</span></span></button>\n"
    "\n"
    "    <h3>Stretch goal</h3>\n"
    "    <button class=\"btn danger\" data-q=\"do=multi\"><span class=\"n\">M</span><span>Multiple simultaneous failures<span class=\"h\">UI + logger killed, DM invalid op</span></span></button>\n"
    "\n"
    "    <h3>Operator</h3>\n"
    "    <button class=\"btn\" data-q=\"do=reset\"><span class=\"n\">R</span><span>Reset alarm / release trip<span class=\"h\">refused while vibration is zone C or D</span></span></button>\n"
    "    <button class=\"btn\" data-q=\"do=qclear\"><span class=\"n\">Q</span><span>Clear request quarantine</span></button>\n"
    "\n"
    "    <h3>Result</h3>\n"
    "    <div class=\"result\" id=\"result\">Ready.</div>\n"
    "    <div class=\"hist mono\" id=\"hist\"></div>\n"
    "  </section>\n"
    "</aside>\n"
    "</div>\n"
    "\n"
    "<script>\n"
    "\"use strict\";\n"
    "const $ = (id) => document.getElementById(id);\n"
    "const css = (v) => getComputedStyle(document.documentElement).getPropertyValue(v).trim();\n"
    "const C = {};\n"
    "[\"--good\",\"--warning\",\"--serious\",\"--critical\",\"--idle\",\"--series-1\",\"--series-2\",\"--grid\",\"--text-muted\",\"--text-secondary\",\"--surface-1\",\"--surface-2\",\"--border\"]\n"
    "  .forEach(k => C[k.slice(2)] = css(k));\n"
    "const STATE_COLOR = { RUNNING: C.good, RECOVERING: C.serious, STARTING: C[\"series-1\"], VERIFYING: C.warning, FAILED: C.critical, STOPPED: C.idle };\n"
    "const STATE_CLASS = { RUNNING: \"good\", RECOVERING: \"serious\", STARTING: \"info\", VERIFYING: \"warning\", FAILED: \"critical\", STOPPED: \"idle\" };\n"
    "const ROLE = { sensor: \"critical \302\267 node data\", dm: \"critical \302\267 machine control\", logger: \"data logger\",\n"
    "               ui: \"non-critical\", statusfs: \"resource manager\", webui: \"this dashboard\" };\n"
    "const esc = (s) => String(s \?\? \"\").replace(/[&<>\"]/g, c => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" }[c]));\n"
    "const fx = (v, d = 1) => v == null || !isFinite(v) \? \"-\" : Number(v).toFixed(d);\n"
    "const ms = (v) => v == null || v < 0 \? \"-\" : v >= 10000 \? (v / 1000).toFixed(1) + \" s\" : Math.round(v) + \" ms\";\n"
    "const ago = (msv) => msv < 0 \? \"-\" : msv < 1000 \? \"now\" : msv < 60000 \? Math.round(msv / 1000) + \" s ago\" : Math.round(msv / 60000) + \" min ago\";\n"
    "\n"
    "/* ---------- client-side history ---------- */\n"
    "const WINDOW = 120000;    // charts: 2 minutes kept\n"
    "let TL_WIN = 30000;       // process timeline: shorter, so a 0.6 s recovery is visible\n"
    "const tl = [];            // {t, st: {key: state}}\n"
    "const tempHist = [];      // [t, temp]\n"
    "const logSeen = new Map();\n"
    "const alarmSeen = new Map();\n"
    "let last = null, linkOk = false, firstData = true, logFilter = \"all\";\n"
    "let clockOff = 0;                 // Date.now() - Pi monotonic ms\n"
    "const recHist = new Map();        // recoveries kept by id (the server sends the last 12)\n"
    "const supHist = new Map();        // supervisor takeovers\n"
    "\n"
    "/* ---------- canvas helpers ---------- */\n"
    "function setupCanvas(el) {\n"
    "  const cv = el.querySelector(\"canvas\");\n"
    "  const w = el.clientWidth, h = +cv.getAttribute(\"height\");\n"
    "  const r = window.devicePixelRatio || 1;\n"
    "  if (cv.width !== Math.round(w * r)) { cv.width = Math.round(w * r); cv.height = Math.round(h * r); cv.style.height = h + \"px\"; }\n"
    "  const g = cv.getContext(\"2d\");\n"
    "  g.setTransform(r, 0, 0, r, 0, 0);\n"
    "  g.clearRect(0, 0, w, h);\n"
    "  g.font = \"11px system-ui, sans-serif\";\n"
    "  return { g, w, h };\n"
    "}\n"
    "function niceMax(v) { const p = Math.pow(10, Math.floor(Math.log10(v))); for (const m of [1, 2, 2.5, 5, 10]) if (m * p >= v) return m * p; return 10 * p; }\n"
    "function ticks(max, n = 5) { const st = niceMax(max / n - 1e-9); const t = []; for (let v = 0; v <= max + 1e-9; v += st) t.push(+v.toFixed(6)); return t; }\n"
    "\n"
    "function timeAxis(g, x0, x1, yb, win = WINDOW) {\n"
    "  g.fillStyle = C[\"text-muted\"]; g.textAlign = \"center\"; g.textBaseline = \"top\";\n"
    "  const span = win / 1000, step = span / 6;\n"
    "  for (let s = span; s >= 0; s -= step) {\n"
    "    const x = x1 - (s * 1000 / win) * (x1 - x0);\n"
    "    g.textAlign = s < 0.01 \? \"right\" : s > span - 0.01 \? \"left\" : \"center\";   // ends kept clear of the y labels\n"
    "    g.fillText(s < 0.01 \? \"now\" : \"-\" + Math.round(s) + \" s\", x, yb + 4);\n"
    "  }\n"
    "}\n"
    "\n"
    "/* vibration chart: series from the EDR ring (server side), ISO bands */\n"
    "function drawVib(d) {\n"
    "  const el = $(\"ch-vib\"), { g, w, h } = setupCanvas(el);\n"
    "  const L = 44, R = 76, T = 8, B = 22, x0 = L, x1 = w - R, y0 = T, yb = h - B;\n"
    "  const m = d.machine, pts = d.edr.filter(p => p[1] != null);\n"
    "  const zab = m.zone_ab, zbc = m.zone_bc, zcd = m.zone_cd;\n"
    "  // y-axis: fits the data, but never more than 2x the zone D limit - one 280 mm/s shake would\n"
    "  // otherwise squash zones A-C into a few pixels; values above are drawn on the top edge in red\n"
    "  const cap = zcd * 2, top = Math.max(0, ...pts.map(p => p[1]));\n"
    "  let vmax = Math.min(Math.max(zcd * 1.3, top * 1.05), cap);\n"
    "  const vstep = niceMax(vmax / 5); vmax = Math.ceil(vmax / vstep) * vstep;\n"
    "  const Y = (v) => yb - (Math.min(v, vmax) / vmax) * (yb - y0);\n"
    "  const X = (t) => x1 + (t / WINDOW) * (x1 - x0);\n"
    "  const bands = [[0, zab, \"#0ca30c40\", \"A good\"], [zab, zbc, \"#0ca30c1c\", \"B acceptable\"], [zbc, zcd, \"#fab2192e\", \"C alert\"], [zcd, vmax, \"#d03b3b38\", \"D danger\"]];\n"
    "  for (const [a, b, col, lab] of bands) {\n"
    "    if (a >= vmax) continue;\n"
    "    g.fillStyle = col; g.fillRect(x0, Y(b), x1 - x0, Y(a) - Y(b));\n"
    "    g.fillStyle = C[\"text-secondary\"]; g.textAlign = \"left\"; g.textBaseline = \"middle\";\n"
    "    const yy = (Y(a) + Y(Math.min(b, vmax))) / 2;\n"
    "    if (Y(a) - Y(Math.min(b, vmax)) > 11) g.fillText(lab, x1 + 6, yy);\n"
    "  }\n"
    "  g.strokeStyle = C.grid; g.lineWidth = 1; g.fillStyle = C[\"text-muted\"]; g.textAlign = \"right\"; g.textBaseline = \"middle\";\n"
    "  for (const t of ticks(vmax)) { const y = Math.round(Y(t)) + .5; g.beginPath(); g.moveTo(x0, y); g.lineTo(x1, y); g.stroke(); g.fillText(fx(t, t < 10 \? 1 : 0), x0 - 6, y); }\n"
    "  g.save(); g.translate(11, (y0 + yb) / 2); g.rotate(-Math.PI / 2); g.textAlign = \"center\"; g.fillText(\"mm/s RMS\", 0, 0); g.restore();\n"
    "  timeAxis(g, x0, x1, yb);\n"
    "  if (!pts.length) {\n"
    "    g.fillStyle = C[\"text-muted\"]; g.textAlign = \"center\"; g.textBaseline = \"middle\";\n"
    "    g.fillText(m.node < 0 \? \"No vibration node alive \342\200\224 machine protection inactive\" : \"Waiting for data\", (x0 + x1) / 2, (y0 + yb) / 2);\n"
    "  } else {\n"
    "    g.strokeStyle = C[\"series-1\"]; g.lineWidth = 2; g.lineJoin = \"round\"; g.beginPath();\n"
    "    let prev = null;\n"
    "    for (const p of pts) {\n"
    "      const x = X(p[0]), y = Y(p[1]);\n"
    "      if (x < x0) { prev = p; continue; }\n"
    "      if (!prev || p[0] - prev[0] > 2500) g.moveTo(x, y); else g.lineTo(x, y);  // gap when the node was silent\n"
    "      prev = p;\n"
    "    }\n"
    "    g.stroke();\n"
    "    // off-scale stretches: red on the top edge, the peak of each stretch labelled\n"
    "    let run = null; const runs = [];\n"
    "    for (const p of pts) {\n"
    "      if (X(p[0]) < x0) continue;\n"
    "      if (p[1] > vmax) { if (!run || p[0] - run.b > 1200) runs.push(run = { a: p[0], b: p[0], pk: p[1], t: p[0] }); else { run.b = p[0]; if (p[1] > run.pk) { run.pk = p[1]; run.t = p[0]; } } }\n"
    "    }\n"
    "    g.fillStyle = C.critical; g.textAlign = \"center\"; g.textBaseline = \"top\";\n"
    "    let lastLab = -1e9;\n"
    "    for (const r of runs) {\n"
    "      const xa = X(r.a) - 2, xb = X(r.b) + 2;\n"
    "      g.fillRect(xa, y0, Math.max(4, xb - xa), 3);\n"
    "      const xt = X(r.t);\n"
    "      g.beginPath(); g.moveTo(xt - 4, y0 + 10); g.lineTo(xt + 4, y0 + 10); g.lineTo(xt, y0 + 4); g.fill();\n"
    "      if (xt - lastLab > 46) {\n"
    "        const lab = fx(r.pk, 0) + \" \342\226\262\", tw = g.measureText(lab).width + 8, xc = Math.min(x1 - tw / 2, Math.max(x0 + tw / 2, xt));\n"
    "        g.fillStyle = C[\"surface-1\"]; g.fillRect(xc - tw / 2, y0 + 12, tw, 15);\n"
    "        g.fillStyle = C.critical; g.fillText(lab, xc, y0 + 13); lastLab = xt;\n"
    "      }\n"
    "    }\n"
    "    if (runs.length) { g.fillStyle = C[\"text-secondary\"]; g.textAlign = \"left\"; g.fillText(\"\342\226\262 off scale\", x1 + 6, y0); }\n"
    "    const lp = pts[pts.length - 1];\n"
    "    g.fillStyle = C[\"series-1\"]; g.beginPath(); g.arc(X(lp[0]), Y(lp[1]), 4, 0, 7); g.fill();\n"
    "    g.strokeStyle = C[\"surface-1\"]; g.lineWidth = 2; g.stroke();\n"
    "  }\n"
    "  el._hover = { x0, x1, y0, yb, find(mx) {\n"
    "    if (!pts.length) return null;\n"
    "    const t = (mx - x1) / (x1 - x0) * WINDOW;\n"
    "    let best = pts[0]; for (const p of pts) if (Math.abs(p[0] - t) < Math.abs(best[0] - t)) best = p;\n"
    "    return { x: X(best[0]), y: Y(best[1]), html: `<b>${fx(best[1], 2)} mm/s</b> &middot; zone ${\"ABCD\"[best[3]] \?\? \"\?\"}<br><span style=\"color:${C[\"text-muted\"]}\">${fx(-best[0] / 1000, 1)} s ago</span>` };\n"
    "  } };\n"
    "}\n"
    "\n"
    "function drawTemp(d) {\n"
    "  const el = $(\"ch-temp\"), { g, w, h } = setupCanvas(el);\n"
    "  const L = 36, R = 10, T = 8, B = 22, x0 = L, x1 = w - R, y0 = T, yb = h - B;\n"
    "  const now = Date.now(), pts = tempHist.filter(p => now - p[0] <= WINDOW);\n"
    "  const warn = d.machine.temp_warn, max = d.machine.temp_max;\n"
    "  const vals = pts.map(p => p[1]);\n"
    "  let lo = Math.min(...vals, warn) - 2, hi = Math.max(...vals, max) + 2;\n"
    "  lo = Math.floor(lo / 5) * 5; hi = Math.ceil(hi / 5) * 5;\n"
    "  const Y = (v) => yb - (v - lo) / (hi - lo) * (yb - y0);\n"
    "  const X = (t) => x1 - ((now - t) / WINDOW) * (x1 - x0);\n"
    "  g.strokeStyle = C.grid; g.lineWidth = 1; g.fillStyle = C[\"text-muted\"]; g.textAlign = \"right\"; g.textBaseline = \"middle\";\n"
    "  for (let v = lo; v <= hi; v += (hi - lo) > 30 \? 10 : 5) { const y = Math.round(Y(v)) + .5; g.beginPath(); g.moveTo(x0, y); g.lineTo(x1, y); g.stroke(); g.fillText(v, x0 - 6, y); }\n"
    "  // the two limit lines: labels on the right, the warn label below its line if the two are close\n"
    "  const close = Math.abs(Y(warn) - Y(max)) < 14;\n"
    "  for (const [v, col, lab, below] of [[warn, C.warning, \"warn \" + fx(warn, 0), close], [max, C.critical, \"alarm \" + fx(max, 0), false]]) {\n"
    "    g.setLineDash([5, 4]); g.strokeStyle = col; g.lineWidth = 1.5; g.beginPath(); g.moveTo(x0, Y(v)); g.lineTo(x1, Y(v)); g.stroke(); g.setLineDash([]);\n"
    "    g.fillStyle = C[\"text-secondary\"]; g.textAlign = \"right\"; g.textBaseline = below \? \"top\" : \"bottom\"; g.fillText(lab + \" \302\260C\", x1 - 4, Y(v) + (below \? 2 : -2));\n"
    "  }\n"
    "  timeAxis(g, x0, x1, yb);\n"
    "  if (!pts.length) {\n"
    "    g.fillStyle = C[\"text-muted\"]; g.textAlign = \"center\"; g.textBaseline = \"middle\";\n"
    "    g.fillText(d.machine.env_node < 0 \? \"No environment node alive\" : \"Collecting\342\200\246\", (x0 + x1) / 2, (y0 + yb) / 2);\n"
    "  } else {\n"
    "    g.strokeStyle = C[\"series-2\"]; g.lineWidth = 2; g.beginPath();\n"
    "    let prev = null;\n"
    "    for (const p of pts) { const x = X(p[0]), y = Y(p[1]); if (!prev || p[0] - prev[0] > 3000) g.moveTo(x, y); else g.lineTo(x, y); prev = p; }\n"
    "    g.stroke();\n"
    "  }\n"
    "  el._hover = { x0, x1, y0, yb, find(mx) {\n"
    "    if (!pts.length) return null;\n"
    "    const t = now - (x1 - mx) / (x1 - x0) * WINDOW;\n"
    "    let best = pts[0]; for (const p of pts) if (Math.abs(p[0] - t) < Math.abs(best[0] - t)) best = p;\n"
    "    return { x: X(best[0]), y: Y(best[1]), html: `<b>${fx(best[1], 1)} \302\260C</b><br><span style=\"color:${C[\"text-muted\"]}\">${fx((now - best[0]) / 1000, 0)} s ago</span>` };\n"
    "  } };\n"
    "}\n"
    "\n"
    "/* process state timeline (sampled by this page every poll) */\n"
    "const LANES = () => [{ key: \"supervisor\", label: \"Supervisor\" }, { key: \"watchdog\", label: \"Watchdog\" },\n"
    "  ...(last \? last.svc.map(s => ({ key: s.key, label: s.title })) : [])];\n"
    "function drawTimeline() {\n"
    "  const el = $(\"ch-tl\"), { g, w, h } = setupCanvas(el);\n"
    "  const lanes = LANES(), L = 128, R = 10, T = 4, B = 22, x0 = L, x1 = w - R, yb = h - B;\n"
    "  const lh = (yb - T) / lanes.length, now = Date.now();\n"
    "  const X = (t) => x1 - ((now - t) / TL_WIN) * (x1 - x0);\n"
    "  lanes.forEach((ln, i) => {\n"
    "    const y = T + i * lh;\n"
    "    g.fillStyle = C[\"text-secondary\"]; g.textAlign = \"right\"; g.textBaseline = \"middle\";\n"
    "    g.fillText(ln.label, x0 - 8, y + lh / 2);\n"
    "    g.fillStyle = \"#2e2e2b\"; g.fillRect(x0, y + 3, x1 - x0, lh - 6);\n"
    "    for (let k = 0; k < tl.length; ) {           // merge equal samples into runs\n"
    "      const st = tl[k].st[ln.key]; let j = k + 1;\n"
    "      while (j < tl.length && tl[j].st[ln.key] === st) j++;\n"
    "      if (st) {\n"
    "        const xa = Math.max(x0, Math.round(X(tl[k].t))), xb = j < tl.length \? Math.round(X(tl[j].t)) : x1;\n"
    "        if (xb >= x0) { g.fillStyle = STATE_COLOR[st] || C.idle; g.fillRect(xa, y + 3, Math.max(st === \"RUNNING\" \? 2 : 4, xb - xa), lh - 6); }\n"
    "      }\n"
    "      k = j;\n"
    "    }\n"
    "  });\n"
    "  // exact recovery stages from the supervisor's timestamps (the 2 Hz sampling above would miss them)\n"
    "  if (last) {\n"
    "    const off = clockOff, idx = Object.fromEntries(lanes.map((l, i) => [l.key, i]));\n"
    "    const seg = (key, a, b, col) => {\n"
    "      if (!a || !b || b < a || idx[key] == null) return;\n"
    "      const xa = X(a + off), xb = X(b + off); if (xb < x0) return;\n"
    "      g.fillStyle = col; g.fillRect(Math.max(x0, Math.round(xa)), T + idx[key] * lh + 3, Math.max(4, Math.round(xb - Math.max(x0, xa))), lh - 6);\n"
    "    };\n"
    "    for (const r of recHist.values()) {\n"
    "      const f = r.t0 || r.fail;\n"
    "      seg(r.svc, f, r.spawn || r.detect || f + 2, C.serious);\n"
    "      seg(r.svc, r.spawn, r.ready, C[\"series-1\"]);\n"
    "      seg(r.svc, r.ready, r.healthy, C.warning);\n"
    "    }\n"
    "    for (const s of supHist.values()) seg(\"supervisor\", s.fail, s.fail + s.ms, C.critical);\n"
    "  }\n"
    "  timeAxis(g, x0, x1, yb, TL_WIN);\n"
    "  el._hover = { x0, x1, y0: T, yb, find(mx, my) {\n"
    "    const i = Math.floor((my - T) / lh); if (i < 0 || i >= lanes.length) return null;\n"
    "    const t = now - (x1 - mx) / (x1 - x0) * TL_WIN;\n"
    "    let s = null; for (const a of tl) { if (a.t <= t) s = a; else break; }\n"
    "    if (!s || !s.st[lanes[i].key]) return null;\n"
    "    return { x: mx, y: T + i * lh + lh / 2, html: `<b>${esc(lanes[i].label)}</b>: ${s.st[lanes[i].key]}<br><span style=\"color:${C[\"text-muted\"]}\">${fx((now - t) / 1000, 1)} s ago</span>` };\n"
    "  } };\n"
    "}\n"
    "\n"
    "function hoverable(el) {\n"
    "  const tip = el.querySelector(\".tip\");\n"
    "  el.addEventListener(\"mousemove\", (ev) => {\n"
    "    const r = el.getBoundingClientRect(), mx = ev.clientX - r.left, my = ev.clientY - r.top, hv = el._hover;\n"
    "    const f = hv && mx >= hv.x0 && mx <= hv.x1 \? hv.find(mx, my) : null;\n"
    "    if (!f) { tip.style.display = \"none\"; return; }\n"
    "    tip.innerHTML = f.html; tip.style.display = \"block\";\n"
    "    const tw = tip.offsetWidth;\n"
    "    tip.style.left = Math.min(el.clientWidth - tw - 4, Math.max(0, f.x + 12)) + \"px\";\n"
    "    tip.style.top = Math.max(0, f.y - 40) + \"px\";\n"
    "  });\n"
    "  el.addEventListener(\"mouseleave\", () => tip.style.display = \"none\");\n"
    "}\n"
    "[\"ch-vib\", \"ch-temp\", \"ch-tl\"].forEach(id => hoverable($(id)));\n"
    "\n"
    "/* ---------- panels ---------- */\n"
    "function chip(id, cls, label, value) { $(id).innerHTML = `<span class=\"dot s-${cls}\"></span><span class=\"k\">${label}</span> <b>${esc(value)}</b>`; }\n"
    "\n"
    "function renderHeader(d) {\n"
    "  $(\"ver\").textContent = \"v\" + d.v;\n"
    "  const m = d.dm.mode, cls = d.safe \? \"critical\" : { NORMAL: \"good\", DEGRADED: \"warning\", ALERT: \"warning\", SAFE: \"critical\", BOOT: \"idle\" }[m] || \"idle\";\n"
    "  chip(\"c-mode\", cls, \"System\", d.safe \? \"SAFE STATE\" : m + (d.dm.restricted \? \" \302\267 RESTRICTED\" : \"\"));\n"
    "  if (d.dm.tripped) chip(\"c-machine\", \"critical\", \"Machine\", \"TRIPPED (stopped)\");\n"
    "  else if (d.machine.node < 0) chip(\"c-machine\", \"idle\", \"Machine\", \"no vibration node\");\n"
    "  else chip(\"c-machine\", d.machine.running \? \"good\" : \"idle\", \"Machine\", d.machine.running \? \"RUNNING\" : \"IDLE\");\n"
    "  const vias = new Set(d.nodes.filter(n => n.alive).map(n => n.via));\n"
    "  let src = \"no nodes\", sc = \"idle\";\n"
    "  if (vias.size === 1 && vias.has(\"node_sim (laptop)\")) { src = \"node_sim on \" + (d.laptop || \"laptop\"); sc = \"info\"; }\n"
    "  else if (vias.size === 1 && vias.has(\"Wi-Fi node\")) { src = \"real Wi-Fi nodes\"; sc = \"good\"; }\n"
    "  else if (vias.size > 1) { src = \"mixed (sim + real)\"; sc = \"warning\"; }\n"
    "  chip(\"c-src\", sc, \"Data source\", src);\n"
    "  const s = Math.floor(d.uptime_ms / 1000);\n"
    "  $(\"c-up\").textContent = `${Math.floor(s / 3600)}:${String(Math.floor(s / 60) % 60).padStart(2, \"0\")}:${String(s % 60).padStart(2, \"0\")}`;\n"
    "}\n"
    "\n"
    "function tileHTML(o) {\n"
    "  const pct = o.limit > 0 && o.age >= 0 \? Math.min(100, 100 * o.age / o.limit) : 0;\n"
    "  const bar = pct > 80 \? C.critical : pct > 50 \? C.warning : C.good;\n"
    "  return `<div class=\"tile t-${o.cls}\">\n"
    "    <div class=\"name\" title=\"${esc(o.name)}\">${esc(o.name)}</div>\n"
    "    <div class=\"role\">${esc(o.role)}</div>\n"
    "    <div class=\"state\"><span class=\"dot s-${o.cls}\"></span>${esc(o.state)}${o.tag \? ` <span class=\"tag\">${esc(o.tag)}</span>` : \"\"}</div>\n"
    "    <div class=\"hbbar\" title=\"heartbeat age ${o.age} ms of ${o.limit} ms\"><i style=\"width:${pct}%;background:${bar}\"></i></div>\n"
    "    <dl>${o.rows.map(([k, v]) => `<dt>${k}</dt><dd class=\"num\">${esc(v)}</dd>`).join(\"\")}</dl></div>`;\n"
    "}\n"
    "function renderTiles(d) {\n"
    "  const t = [];\n"
    "  const supOk = d.sup.hb_age >= 0 && d.sup.hb_age < 300;\n"
    "  t.push(tileHTML({ name: \"Supervisor\", role: \"recovery manager \302\267 prio 63 core 1\", state: supOk \? \"RUNNING\" : \"SILENT\",\n"
    "    cls: supOk \? \"good\" : \"critical\", age: d.sup.hb_age, limit: 300,\n"
    "    rows: [[\"PID\", d.sup.pid], [\"HB age\", ms(d.sup.hb_age)], [\"Takeovers\", d.sup.restarts], [\"Last\", d.sup.restarts \? ms(d.sup.takeover_ms) : \"-\"]] }));\n"
    "  const wdOk = d.wd.hb_age >= 0 && d.wd.hb_age < 500;\n"
    "  t.push(tileHTML({ name: \"Watchdog\", role: \"watches supervisor \302\267 prio 62 core 0\", state: wdOk \? \"RUNNING\" : \"SILENT\",\n"
    "    cls: wdOk \? \"good\" : \"critical\", age: d.wd.hb_age, limit: 500,\n"
    "    rows: [[\"PID\", d.wd.pid], [\"HB age\", ms(d.wd.hb_age)], [\"Restarts\", d.wd.restarts], [\"Watches\", \"supervisor\"]] }));\n"
    "  for (const s of d.svc) {\n"
    "    t.push(tileHTML({ name: s.title, role: `${ROLE[s.key] || \"\"} \302\267 prio ${s.prio} core ${s.cpu}`, state: s.state,\n"
    "      cls: STATE_CLASS[s.state] === \"info\" \? \"warning\" : STATE_CLASS[s.state] || \"idle\", age: s.hb_age, limit: s.hb_limit,\n"
    "      tag: s.adopted \? \"adopted\" : \"\",\n"
    "      rows: [[\"PID\", s.pid], [\"HB age\", ms(s.hb_age)], [\"Restarts\", s.restarts + (s.failed \? ` (${s.failed} failed)` : \"\")],\n"
    "             [\"Avail.\", s.avail == null \? \"-\" : fx(s.avail, 2) + \" %\"], [\"Latency\", s.lat_ms \? fx(s.lat_ms, 2) + \" ms\" : \"-\"],\n"
    "             ...(s.key === \"dm\" \? [[\"Clients\", s.clients]] : [])] }));\n"
    "  }\n"
    "  $(\"tiles\").innerHTML = t.join(\"\");\n"
    "}\n"
    "\n"
    "const ZCOL = { A: C.good, B: \"#7bc47b\", C: C.warning, D: C.critical };\n"
    "function renderStatus(d) {\n"
    "  const m = d.machine;\n"
    "  $(\"vib-src\").textContent = m.node < 0 \? \"no vibration node alive\" : `node ${m.node} \\u00b7 ${fx(m.vel, 2)} mm/s now, zone ${m.zone}`;\n"
    "  $(\"env-src\").textContent = m.env_node < 0 \? \"no environment node alive\" : `node ${m.env_node} \\u00b7 ${fx(m.env_temp, 1)} \\u00b0C now`;\n"
    "  const w = [];\n"
    "  if (d.dm.tripped) w.push([\"critical\", \"MACHINE TRIPPED\"]);\n"
    "  if (d.dm.latched) w.push([\"warning\", \"Alarm latched #\" + d.dm.latched_id]);\n"
    "  if (d.dm.restricted) w.push([\"critical\", \"RESTRICTED (safe-init)\"]);\n"
    "  if (d.safe) w.push([\"critical\", \"SYSTEM SAFE STATE (critical service FAILED)\"]);\n"
    "  if (m.warnings && m.warnings !== \"none\" && m.warnings !== \"-\") m.warnings.split(/[ ,]+/).filter(Boolean).forEach(x => w.push([\"warning\", x]));\n"
    "  if (d.stress > 0) w.push([\"serious\", `CPU load test ${Math.ceil(d.stress / 1000)} s`]);\n"
    "  if (d.quar.length) w.push([\"serious\", d.quar.length + \" request(s) quarantined\"]);\n"
    "  if (!m.dm_link) w.push([\"warning\", \"Sensor \\u2192 Device Manager link DOWN\"]);\n"
    "  w.push([\"idle\", `critical loop: ${m.misses} deadline misses, max late ${fx(m.max_late, 2)} ms`]);\n"
    "  if (w.length === 1) w.unshift([\"good\", \"No warnings\"]);\n"
    "  $(\"warnbar\").innerHTML = w.map(([c, t]) => `<span class=\"chip\"><span class=\"dot s-${c}\"></span>${esc(t)}</span>`).join(\"\");\n"
    "}\n"
    "\n"
    "const STAGES = [[\"Detect\", \"fail\", \"detect\", C.critical, \"fault \342\206\222 supervisor noticed\"],\n"
    "  [\"Restart\", \"detect\", \"spawn\", C.serious, \"new process created\"],\n"
    "  [\"Restore\", \"spawn\", \"ready\", C[\"series-1\"], \"checkpoint loaded, READY\"],\n"
    "  [\"Verify\", \"ready\", \"healthy\", C.warning, \"heartbeats + PING\"],\n"
    "  [\"Reconnect\", \"healthy\", \"reconnect\", C.good, \"clients reconnected\"]];\n"
    "function recDur(r, a, b) { const A = a === \"fail\" \? (r.t0 || r.fail) : r[a]; return A && r[b] && r[b] >= A \? r[b] - A : null; }\n"
    "const CKS = [\"newest\", \"fallback\", \"safe-init\"];\n"
    "function renderRecovery(d) {\n"
    "  const recs = d.rec;\n"
    "  if (!recs.length) { $(\"rec-empty\").style.display = \"block\"; $(\"rec-body\").innerHTML = \"\"; return; }\n"
    "  $(\"rec-empty\").style.display = \"none\";\n"
    "  const r = recs[recs.length - 1];\n"
    "  const durs = STAGES.map(s => recDur(r, s[1], s[2]));\n"
    "  const total = durs.reduce((a, b) => a + (b || 0), 0);\n"
    "  $(\"rec-title\").innerHTML = `#${r.id} <b>${esc(r.svc)}</b> &middot; ${esc(r.cause)} &middot; ${ago(r.ago_ms)}` +\n"
    "    (r.complete \? ` &middot; total <b class=\"num\">${ms(total)}</b>` : ` &middot; <b style=\"color:${C.warning}\">in progress</b>`);\n"
    "  $(\"rec-bar\").innerHTML = STAGES.map((s, i) => durs[i] == null \? \"\" :\n"
    "    `<div title=\"${s[0]} ${ms(durs[i])}\" style=\"flex:${Math.max(durs[i], total * 0.02)};background:${s[3]}\"></div>`).join(\"\");\n"
    "  $(\"rec-legend\").innerHTML = STAGES.map((s, i) =>\n"
    "    `<span class=\"pill\"><i class=\"sw\" style=\"background:${s[3]}\"></i>${s[0]}</span><span style=\"color:${C[\"text-muted\"]}\">${s[4]}</span><span class=\"num\">${durs[i] == null \? \"-\" : ms(durs[i])}</span>`).join(\"\") +\n"
    "    `<span>Checkpoint</span><span style=\"color:${C[\"text-muted\"]}\">expected #${r.ck_exp} restored #${r.ck_res}</span><span>${r.ck < 0 \? \"n/a\" : CKS[r.ck]}</span>`;\n"
    "  $(\"rec-body\").innerHTML = recs.slice().reverse().map(r => {\n"
    "    const det = recDur(r, \"fail\", \"detect\");\n"
    "    const end = r.reconnect || r.healthy; const tot = r.complete && end \? end - (r.t0 || r.fail) : null;\n"
    "    const ck = r.ck < 0 \? \"n/a\" : CKS[r.ck];\n"
    "    const ckc = r.ck === 0 \? \"good\" : r.ck === 1 \? \"warning\" : r.ck === 2 \? \"critical\" : \"idle\";\n"
    "    return `<tr><td class=\"num\">${r.id}</td><td>${esc(r.svc)}</td><td>${esc(r.cause)}</td><td class=\"num\">${ms(det)}</td>\n"
    "      <td class=\"num\">${!r.complete \? \"running\" : r.healthy \? ms(tot) : \"not restarted (FAILED)\"}</td><td><span class=\"pill\"><span class=\"dot s-${ckc}\"></span>${ck}</span></td><td class=\"num\">${r.miss}</td></tr>`;\n"
    "  }).join(\"\");\n"
    "}\n"
    "\n"
    "function renderMetrics(d) {\n"
    "  const done = d.rec.filter(r => r.complete);\n"
    "  const det = done.map(r => recDur(r, \"fail\", \"detect\")).filter(v => v != null);\n"
    "  const tot = done.map(r => (r.reconnect || r.healthy) - (r.t0 || r.fail)).filter(v => v >= 0);\n"
    "  const avg = (a) => a.length \? a.reduce((x, y) => x + y, 0) / a.length : null;\n"
    "  const ck = done.filter(r => r.ck >= 0), exact = ck.filter(r => r.ck === 0).length, fb = ck.filter(r => r.ck === 1).length, none = ck.filter(r => r.ck === 2).length;\n"
    "  const failed = d.svc.reduce((a, s) => a + s.failed, 0);\n"
    "  const missRec = d.rec.reduce((a, r) => a + r.miss, 0);\n"
    "  const minAvail = Math.min(...d.svc.filter(s => s.crit && s.avail != null).map(s => s.avail));\n"
    "  const M = [\n"
    "    [\"Detection time\", det.length \? ms(det[det.length - 1]) : \"-\", det.length \? `avg ${ms(avg(det))} \302\267 worst ${ms(Math.max(...det))}` : \"no faults yet\"],\n"
    "    [\"Restoration time\", tot.length \? ms(tot[tot.length - 1]) : \"-\", tot.length \? `avg ${ms(avg(tot))} \302\267 worst ${ms(Math.max(...tot))}` : \"fault \342\206\222 healthy\"],\n"
    "    [\"Deadline misses\", d.machine.misses, `critical 100 Hz loop \302\267 ${missRec} during recoveries`],\n"
    "    [\"Lost requests\", d.machine.lost, `${d.machine.ev_created} alarm events created \302\267 ${d.machine.ev_pending} in flight`],\n"
    "    [\"Duplicates rejected\", d.dm.ev_dup + d.dm.req_dup, `stale ${d.dm.req_stale} \302\267 invalid ${d.dm.req_invalid} \302\267 quarantined ${d.dm.req_quar}`],\n"
    "    [\"Checkpoint accuracy\", ck.length \? `${exact}/${ck.length}` : \"-\", `exact newest \302\267 ${fb} fallback \302\267 ${none} safe-init`],\n"
    "    [\"Unsuccessful restarts\", failed, `restarts that failed verification \302\267 ${d.rec_count} recoveries`],\n"
    "    [\"Critical availability\", isFinite(minAvail) \? fx(minAvail, 3) + \" %\" : \"-\", `supervisor takeovers ${d.sup.restarts} \302\267 no reboots`]];\n"
    "  $(\"metrics\").innerHTML = M.map(([l, v, s]) => `<div class=\"metric\"><div class=\"l\">${l}</div><div class=\"v num\">${esc(v)}</div><div class=\"s\">${esc(s)}</div></div>`).join(\"\");\n"
    "}\n"
    "\n"
    "const AL_NAME = { VIBRATION_DANGER: \"Vibration danger (zone D)\", OVER_TEMPERATURE: \"Over-temperature\", SENSOR_MOUNT_LOOSE: \"Sensor mount loose\" };\n"
    "const AL_UNIT = { VIBRATION_DANGER: \" mm/s\", OVER_TEMPERATURE: \" \302\260C\", SENSOR_MOUNT_LOOSE: \"\302\260 tilt\" };\n"
    "function renderAlarms(d) {\n"
    "  const now = Date.now();\n"
    "  for (const a of d.alarms) {\n"
    "    const o = alarmSeen.get(a.id) || { first: now };\n"
    "    if (a.acked && !o.ackAt) o.ackAt = now;\n"
    "    alarmSeen.set(a.id, Object.assign(o, a, { inLog: true }));\n"
    "  }\n"
    "  const ids = new Set(d.alarms.map(a => a.id));\n"
    "  for (const [id, o] of alarmSeen) if (!ids.has(id)) o.inLog = false;\n"
    "  const list = [...alarmSeen.values()].sort((a, b) => b.id - a.id);\n"
    "  $(\"al-empty\").style.display = list.length \? \"none\" : \"block\";\n"
    "  $(\"al-body\").innerHTML = list.map(a => {\n"
    "    const t = new Date(a.wall).toLocaleTimeString([], { hour12: false });\n"
    "    const del = a.acked \? `<span class=\"pill\"><span class=\"dot s-good\"></span>ACKED (${a.tries} send${a.tries === 1 \? \"\" : \"s\"})</span>`\n"
    "      : !d.dm.centre \? `<span class=\"pill\"><span class=\"dot s-warning\"></span>queued (no centre, -e)</span>`\n"
    "      : `<span class=\"pill\"><span class=\"dot s-serious\"></span>sending, try ${a.tries}</span>`;\n"
    "    const extra = a.type === \"VIBRATION_DANGER\" \? ` @ ${fx(a.freq, 1)} Hz` : \"\";\n"
    "    return `<tr><td class=\"num\">${a.id}</td><td class=\"num\">${t}</td><td>${esc(AL_NAME[a.type] || a.type)}</td><td class=\"num\">${fx(a.value, 2)}${AL_UNIT[a.type] || \"\"}${extra}</td><td class=\"num\">${a.node}</td><td>${del}</td></tr>`;\n"
    "  }).join(\"\");\n"
    "  $(\"al-sum\").textContent = `${d.dm.ev_rx} stored \302\267 ${d.dm.acked} acked \302\267 ${d.dm.retries} resends \302\267 ${d.dm.pending} queued`;\n"
    "}\n"
    "\n"
    "function renderLog(d) {\n"
    "  const now = Date.now();\n"
    "  for (const e of d.log) if (!logSeen.has(e.seq)) logSeen.set(e.seq, Object.assign({ at: now + e.t }, e));\n"
    "  if (logSeen.size > 400) { const ks = [...logSeen.keys()].sort((a, b) => a - b); ks.slice(0, logSeen.size - 400).forEach(k => logSeen.delete(k)); }\n"
    "  const f = logFilter;\n"
    "  const rows = [...logSeen.values()].filter(e => f === \"all\" || (f === \"supervisor\" \? e.src === \"supervisor\" || /watchdog/i.test(e.text)\n"
    "      : f === \"dm\" \? e.src === \"dm\" : e.src !== \"supervisor\" && e.src !== \"dm\")).sort((a, b) => b.seq - a.seq).slice(0, 150);\n"
    "  const name = (s) => s === \"supervisor\" \? \"Supervisor\" : (d.svc.find(x => x.key === s) || {}).title || s;\n"
    "  $(\"log-body\").innerHTML = rows.map(e => `<tr class=\"lv-${e.lvl}\"><td class=\"num\">${new Date(e.at).toLocaleTimeString([], { hour12: false })}</td><td>${esc(name(e.src))}</td><td class=\"wrap\">${esc(e.text)}</td></tr>`).join(\"\");\n"
    "}\n"
    "document.querySelectorAll(\"#logtabs button\").forEach(b => b.onclick = () => {\n"
    "  document.querySelectorAll(\"#logtabs button\").forEach(x => x.classList.toggle(\"on\", x === b));\n"
    "  logFilter = b.dataset.f; if (last) renderLog(last);\n"
    "});\n"
    "\n"
    "function renderCkpt(d) {\n"
    "  $(\"ck-body\").innerHTML = d.svc.filter(s => s.ck).map(s => {\n"
    "    const c = s.ck, rc = c.restore === \"newest\" \? \"good\" : c.restore === \"fallback\" \? \"warning\" : \"critical\";\n"
    "    const rtxt = c.restore === \"none\" \? (c.restored < 0 \? \"none \342\206\222 safe-init\" : \"none\") : `${c.restore} #${c.restored} slot ${c.rslot}`;\n"
    "    return `<tr><td>${esc(s.title)}</td><td>${c.valid \? `<span class=\"pill\"><span class=\"dot s-good\"></span>slot ${c.slot}</span>` : `<span class=\"pill\"><span class=\"dot s-critical\"></span>NO VALID COPY</span>`}</td>\n"
    "      <td class=\"num\">${c.valid \? \"#\" + c.counter : \"-\"}</td><td class=\"num\">${c.valid \? ms(c.age_ms) : \"-\"}</td><td class=\"num\">${c.files}/2</td>\n"
    "      <td><span class=\"pill\"><span class=\"dot s-${rc}\"></span>${rtxt}</span></td></tr>`;\n"
    "  }).join(\"\");\n"
    "}\n"
    "\n"
    "/* ---------- polling ---------- */\n"
    "function sample(d) {\n"
    "  const now = Date.now(), st = {};\n"
    "  clockOff = now - d.mono_ms;\n"
    "  for (const r of d.rec) recHist.set(r.id, r);\n"
    "  if (d.sup.fail_mono && d.sup.restarts) supHist.set(d.sup.restarts, { fail: d.sup.fail_mono, ms: d.sup.takeover_ms || 300 });\n"
    "  st.supervisor = d.sup.hb_age >= 0 && d.sup.hb_age < 300 \? \"RUNNING\" : \"FAILED\";\n"
    "  st.watchdog = d.wd.hb_age >= 0 && d.wd.hb_age < 500 \? \"RUNNING\" : \"FAILED\";\n"
    "  for (const s of d.svc) st[s.key] = s.state;\n"
    "  tl.push({ t: now, st });\n"
    "  if (d.machine.env_node >= 0 && d.machine.env_ok && d.machine.env_temp != null) tempHist.push([now, d.machine.env_temp]);\n"
    "  while (tl.length && now - tl[0].t > WINDOW + 5000) tl.shift();\n"
    "  while (tempHist.length && now - tempHist[0][0] > WINDOW + 5000) tempHist.shift();\n"
    "}\n"
    "function noData() { tl.push({ t: Date.now(), st: {} }); }\n"
    "\n"
    "function render(d) {\n"
    "  renderHeader(d); renderTiles(d); renderStatus(d); renderRecovery(d); renderMetrics(d);\n"
    "  renderAlarms(d); renderLog(d); renderCkpt(d);\n"
    "  drawVib(d); drawTemp(d); drawTimeline();\n"
    "  if (firstData) { fillSelects(d); firstData = false; }\n"
    "}\n"
    "function setLink(ok) {\n"
    "  if (ok === linkOk) return;\n"
    "  linkOk = ok;\n"
    "  $(\"linkbar\").classList.toggle(\"on\", !ok);\n"
    "  $(\"c-link\").innerHTML = ok \? `<span class=\"dot s-good\"></span><b>live</b>` : `<span class=\"dot s-critical\"></span><b>link lost</b>`;\n"
    "}\n"
    "async function poll() {\n"
    "  try {\n"
    "    const ctl = new AbortController(); const to = setTimeout(() => ctl.abort(), 1500);\n"
    "    const r = await fetch(\"/api/state\", { cache: \"no-store\", signal: ctl.signal });\n"
    "    clearTimeout(to);\n"
    "    const d = await r.json();\n"
    "    last = d; setLink(true); sample(d); render(d);\n"
    "  } catch (e) {\n"
    "    setLink(false); noData(); if (last) drawTimeline();\n"
    "  }\n"
    "  setTimeout(poll, 500);\n"
    "}\n"
    "\n"
    "/* ---------- commands ---------- */\n"
    "function fillSelects(d) {\n"
    "  $(\"f-svc\").innerHTML = d.svc.map(s => `<option value=\"${s.key}\">${esc(s.title)}</option>`).join(\"\");\n"
    "  $(\"k-svc\").innerHTML = d.svc.filter(s => s.ck).map(s => `<option value=\"${s.key}\" ${s.key === \"dm\" \? \"selected\" : \"\"}>${esc(s.title)}</option>`).join(\"\");\n"
    "  const l = d.laptop \? `the maintenance laptop (${d.laptop})` : \"the Pi only (start the supervisor with -e <laptop-ip>)\";\n"
    "  $(\"cmd-who\").textContent = `Commands are accepted from ${l}.`;\n"
    "}\n"
    "async function send(q, label) {\n"
    "  const res = $(\"result\");\n"
    "  res.className = \"result\"; res.textContent = label + \" \342\200\246\";\n"
    "  let ok = false, text = \"\";\n"
    "  try {\n"
    "    const r = await fetch(\"/api/action\?\" + q, { method: \"POST\" });\n"
    "    const j = await r.json(); ok = j.ok; text = j.text;\n"
    "  } catch (e) { text = \"no answer (the web service may have been the target)\"; }\n"
    "  res.className = \"result \" + (ok \? \"ok\" : \"bad\");\n"
    "  res.textContent = text;\n"
    "  const h = document.createElement(\"div\");\n"
    "  h.textContent = `${new Date().toLocaleTimeString([], { hour12: false })}  ${label}: ${ok \? \"ok\" : \"failed\"}`;\n"
    "  $(\"hist\").prepend(h);\n"
    "}\n"
    "document.querySelectorAll(\"[data-q]\").forEach(b => b.onclick = () => send(b.dataset.q, b.querySelector(\"span:not(.n)\")\?.firstChild\?.textContent\?.trim() || b.textContent));\n"
    "document.querySelectorAll(\"[data-f]\").forEach(b => { if (b.closest(\"#logtabs\")) return;\n"
    "  b.onclick = () => { const s = $(\"f-svc\").value; send(`do=${b.dataset.f}&svc=${s}`, `${b.textContent} ${s}`); }; });\n"
    "document.querySelectorAll(\"[data-k]\").forEach(b => b.onclick = () => {\n"
    "  const s = $(\"k-svc\").value, r = $(\"k-restart\").checked \? \"&restart=1\" : \"\";\n"
    "  send(`do=ckpt&svc=${s}&op=${b.dataset.k}${r}`, `checkpoint ${b.dataset.k} ${s}${r \? \" + restart\" : \"\"}`);\n"
    "});\n"
    "document.querySelectorAll(\"#pagetabs button\").forEach(b => b.onclick = () => {\n"
    "  document.querySelectorAll(\"#pagetabs button\").forEach(x => x.classList.toggle(\"on\", x === b));\n"
    "  document.body.className = \"p-\" + b.dataset.p;\n"
    "  try { localStorage.setItem(\"mg_page\", b.dataset.p); } catch (e) {}\n"
    "  if (last) render(last);\n"
    "});\n"
    "document.querySelectorAll(\"#tlwin button\").forEach(b => b.onclick = () => {\n"
    "  document.querySelectorAll(\"#tlwin button\").forEach(x => x.classList.toggle(\"on\", x === b));\n"
    "  TL_WIN = +b.dataset.w; if (last) drawTimeline();\n"
    "});\n"
    "try { const pg = localStorage.getItem(\"mg_page\"); if (pg) document.querySelector(`#pagetabs button[data-p=\"${pg}\"]`)\?.click(); } catch (e) {}\n"
    "window.addEventListener(\"resize\", () => last && render(last));\n"
    "poll();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    ;
#endif
